class InputBase {
    int i;
public: InputBase(int v) : i(v) {}
};

class OutputBase {
    int o;
public: OutputBase(int v) : o(v) {}
};

// Order of declaration (InputBase, OutputBase) controls init order
class IOStream : public InputBase, public OutputBase {
public:
    // Initializer list order (Output then Input) ignored:
    // InputBase constructor runs first.
    IOStream(int a, int b) : OutputBase(b), InputBase(a) {}
};
